// than re-casting at each call site. `manifest.json`/`bundle.css` themselves
// are regenerated by the capture CLI; this file is not.

import type { AutoSkeletonSSRManifest } from 'autoskeleton/ssr';
import raw from './manifest.json';

export const manifest = raw as unknown as AutoSkeletonSSRManifest;
